mapper.select:
SELECT FROM tb_crawl_target
use_yn = #{useYn}
ORDER BY lst_chg_dt DESC, crawl_target_no DESC

SELECT crawl_document_no, target_no, url, title, content, url_hash, content_hash, status, http_status, error_message, fetched_at, frst_reg_dt
FROM tb_crawl_document


        target_no = #{targetId}


ORDER BY fetched_at DESC, crawl_document_no DESC
LIMIT #{limit}

SELECT 
FROM tb_crawl_run_log


        target_no = #{targetId}


        AND status = #{status}


        AND failure_code = #{failureCode}


ORDER BY frst_reg_dt DESC, crawl_run_log_no DESC
LIMIT #{limit}

SELECT 
FROM tb_crawl_run_log
WHERE status = 'FAILED'

    AND reviewed = #{reviewed}


    AND failure_code = #{failureCode}

ORDER BY frst_reg_dt DESC, crawl_run_log_no DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM tb_crawl_document
WHERE frst_reg_dt < #{cutoff}
  AND status IN ('FAILED', 'DUPLICATE')
